intentos.respuesta_cruda:
{
  "sql": "SELECT t1.product_category_name_english, ROUND(100.0 * SUM(CASE WHEN t2.payment_installments > 1 THEN 1 ELSE 0 END) / COUNT(DISTINCT t3.order_id), 2) AS pct_pagos_a_plazos FROM product_category_translation t1 LEFT JOIN order_payments t2 ON t2.order_id = t3.order_id JOIN vw_pedidos_validos t3 ON t3.order_id = t2.order_id WHERE t2.payment_type != 'not_defined' AND t1.product_category_name IS NOT NULL GROUP BY t1.product_category_name_english HAVING COUNT(DISTINCT t3.order_id) >= 100 ORDER BY pct_pagos_a_plazos DESC LIMIT 1"
}
